#!/usr/bin/env node
// python-library — stack-conformity gate (INV-121, generated by arbiter, #1312)
// CATALOG: INV-121 enforcement. Fails when the repo-ROOT manifest contradicts the
// CATALOG:   axes declared in arbiter.json (language AND databaseEngine). Self-safety
// CATALOG:   lives HERE at runtime: absent `language` ⇒ exit 0 (PASS, undeclared never
// CATALOG:   fails); absent/`none` `databaseEngine` ⇒ DB-conformity skipped. Independent
// CATALOG:   escapes. Root-scope ONLY — reads ./go.mod, ./package.json, ./*.lock at the
// CATALOG:   target root and NEVER recurses (auto-skips fixtures + node_modules).
// CATALOG: Rejected fold-in into check-collab-mode-wired.mjs (collaborationMode axis,
// CATALOG:   not manifest/lockfile conformity) and check-canonical-paths.mjs (path layout,
// CATALOG:   not declared-vs-actual stack drift) — different axis, different failure mode.
// Exit codes per INV-53: 0=PASS/SKIP, 1=FAIL (contradiction), 2=ERROR.
// Usage: node scripts/check-stack-conformity.mjs [--config=<path>] [--help]

import { readFileSync, existsSync, readdirSync } from 'node:fs'
import { resolve, join } from 'node:path'

const HELP = [
  'Usage: node scripts/check-stack-conformity.mjs [options]',
  '',
  'Fails (exit 1) when the repo-root manifest contradicts arbiter.json axes',
  '(language AND databaseEngine). Root-scope only — never recurses.',
  '',
  'Options:',
  '  --config=<path>  Path to arbiter.json (default: ./arbiter.json)',
  '  --help, -h       Show this help and exit',
].join('\n')

// Database drivers keyed by the engine they imply. A driver in the root manifest
// for an engine OTHER than the declared one is a contradiction.
const DB_DRIVERS = {
  postgresql: ['pg', 'postgres', 'node-postgres', 'pg-promise', 'lib/pq', 'jackc/pgx', 'psycopg2', 'asyncpg', 'postgresql'],
  mysql: ['mysql', 'mysql2', 'go-sql-driver/mysql', 'pymysql', 'mysqlclient'],
  mongodb: ['mongodb', 'mongoose', 'go.mongodb.org/mongo-driver', 'pymongo', 'motor'],
  sqlite: ['better-sqlite3', 'sqlite3', 'mattn/go-sqlite3', 'aiosqlite'],
}

function fail(msg) {
  process.stderr.write(`[INV-121] ${msg}\n`)
  process.exit(1)
}

try {
  const args = process.argv.slice(2)
  if (args.includes('--help') || args.includes('-h')) {
    process.stdout.write(`${HELP}\n`)
    process.exit(0)
  }

  const root = process.cwd()
  const cfgFlag = args.find((a) => a.startsWith('--config='))
  const configPath = cfgFlag ? resolve(cfgFlag.slice('--config='.length)) : resolve(root, 'arbiter.json')

  if (!existsSync(configPath)) {
    process.stdout.write('[INV-121] arbiter.json not found — not an arbiter project, skip.\n')
    process.exit(0)
  }

  let config
  try {
    config = JSON.parse(readFileSync(configPath, 'utf8'))
  } catch {
    fail(`Failed to parse ${configPath}.`)
  }

  // SELF-SAFETY ESCAPE 1: absent `language` ⇒ PASS (undeclared never fails).
  const language = config.language
  if (language === undefined || language === null || language === '') {
    process.stdout.write('[INV-121] language not declared — skip (PASS).\n')
    process.exit(0)
  }

  // ─── Root-manifest snapshot (root-scope only, never recurse) ──────────────
  const pkgPath = join(root, 'package.json')
  const goModPath = join(root, 'go.mod')
  const hasPkg = existsSync(pkgPath)
  const hasGoMod = existsSync(goModPath)

  let pkgText = ''
  if (hasPkg) {
    try {
      pkgText = readFileSync(pkgPath, 'utf8')
    } catch {
      pkgText = ''
    }
  }
  let goModText = ''
  if (hasGoMod) {
    try {
      goModText = readFileSync(goModPath, 'utf8')
    } catch {
      goModText = ''
    }
  }
  // Root *.lock files (package-lock.json, go.sum, poetry.lock, Cargo.lock, ...).
  let lockText = ''
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    if (!entry.isFile()) continue
    if (entry.name.endsWith('.lock') || entry.name === 'package-lock.json' || entry.name === 'go.sum') {
      try {
        lockText += readFileSync(join(root, entry.name), 'utf8')
      } catch {
        // unreadable lock — ignore, manifest signal already collected
      }
    }
  }
  const manifestText = `${pkgText}\n${goModText}\n${lockText}`

  // ─── Language conformity ──────────────────────────────────────────────────
  // go declared but the root is a Node/TS project (package.json, no go.mod).
  if (language === 'go' && hasPkg && !hasGoMod) {
    fail(
      `declared language="go" but the repo-root manifest is a Node project ` +
        `(package.json present, go.mod absent). Root manifest contradicts the declared axis.`,
    )
  }
  // typescript/javascript declared but the root is a Go module (go.mod, no package.json).
  if ((language === 'typescript' || language === 'javascript') && hasGoMod && !hasPkg) {
    fail(
      `declared language="${language}" but the repo-root manifest is a Go module ` +
        `(go.mod present, package.json absent). Root manifest contradicts the declared axis.`,
    )
  }

  // ─── Database conformity ──────────────────────────────────────────────────
  // SELF-SAFETY ESCAPE 2: absent or 'none' databaseEngine ⇒ skip DB conformity.
  const engine = config.databaseEngine == null ? 'none' : config.databaseEngine
  if (engine !== 'none' && engine !== 'other') {
    const declaredDrivers = new Set(DB_DRIVERS[engine] ?? [])
    for (const [otherEngine, drivers] of Object.entries(DB_DRIVERS)) {
      if (otherEngine === engine) continue
      for (const driver of drivers) {
        if (declaredDrivers.has(driver)) continue
        // Word-ish boundary match: driver token quoted/pathed in a manifest.
        const re = new RegExp(`(^|[^\\w/.-])${driver.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\$&')}([^\\w/.-]|$)`, 'm')
        if (re.test(manifestText)) {
          fail(
            `declared databaseEngine="${engine}" but the repo-root manifest references the ` +
              `"${driver}" driver (implies "${otherEngine}"). Database axis contradicted.`,
          )
        }
      }
    }
  }

  process.stdout.write(`[INV-121] stack conformity OK (language="${language}", databaseEngine="${engine}").\n`)
  process.exit(0)
} catch (err) {
  process.stderr.write(`[INV-121] ERROR: ${err instanceof Error ? err.message : String(err)}\n`)
  process.exit(2)
}
